var T = flow.get('TOKEN') || '';
if(!T){ node.status({fill:'red',shape:'dot',text:'No token — wait'}); return null; }
var path = '/v1.0/devices/' + D + '/door-lock/temp-passwords';
var t   = String(Date.now());
var bh  = crypto.createHash('sha256').update('').digest('hex');
var sts = 'GET\n' + bh + '\n\n' + path;
var sig = crypto.createHmac('sha256',S).update(C+T+t+sts).digest('hex').toUpperCase();
msg.method  = 'GET';
msg.url     = B + path;
msg.payload = '';
msg.headers = {'client_id':C,'access_token':T,'sign_method':'HMAC-SHA256','t':t,'nonce':'','sign':sig,'Content-Type':'application/json'};
return msg;

if(!msg.payload||!msg.payload.success){ return null; }
var users = msg.payload.result || [];
var map   = {};
users.forEach(function(u){
  map[String(u.sn)] = {name:u.name||('User '+u.sn),
    type:u.type===0?'Permanent':'Temporary',
    active:u.phase===2};
});
flow.set('tempUsers', map);
node.status({fill:'green',shape:'dot',text:users.length+' users loaded'});
return null;

var data = msg.payload;
var tempUsers = flow.get('tempUsers') || {};

var UNLOCK = {
  'unlock_fingerprint':'👆 Fingerprint',
  'unlock_password':   '🔢 Password',
  'unlock_temporary':  '🔑 Temp Code',
  'unlock_card':       '💳 Card',
  'unlock_face':       '😊 Face',
  'unlock_key':        '🗝 Physical Key',
  'unlock_app':        '📱 App/Remote',
  'unlock_hand':       '✋ Hand'
};
var ALARM = {
  'wrong_finger':  '⚠️ Wrong Fingerprint',
  'wrong_password':'⚠️ Wrong Password',
  'wrong_card':    '⚠️ Wrong Card',
  'pry':           '🚨 Lock Pried!',
  'low_battery':   '🔋 Low Battery',
  'shock':         '🚨 Shock Detected',
  'defense':       '🚨 Defense Mode'
};

var ts = new Date().toLocaleString('en-GB',{timeZone:'Asia/Riyadh'});
var event = null;

Object.keys(data).forEach(function(key){
  var val = data[key];

  // Unlock event
  if(UNLOCK[key] && parseInt(val) > 0){
    var uid  = parseInt(val);
    var uname= 'User #'+uid;
    if(key==='unlock_temporary' && tempUsers[String(uid)])
      uname = tempUsers[String(uid)].name + ' (ID:'+uid+')';
    event = {type:'UNLOCK', method:UNLOCK[key],
             userId:uid, userName:uname, time:ts, raw:data};
  }

  // Alarm event
  if(key==='alarm_lock' && ALARM[val])
    event = {type:'ALARM', method:ALARM[val], userId:null, time:ts, raw:data};

  // Battery
  if(key==='residual_electricity'){
    flow.set('battery', val+'%');
    if(parseInt(val)<20)
      event = {type:'ALARM', method:'🔋 Low Battery: '+val+'%', userId:null, time:ts, raw:data};
  }

  // Doorbell
  if(key==='doorbell' && val===true)
    event = {type:'DOORBELL', method:'🔔 Doorbell pressed', userId:null, time:ts, raw:data};

  // Arm/disarm
  if(key==='arming_switch')
    event = {type:val?'ARMED':'DISARMED', method:val?'🔒 Armed':'🔓 Disarmed',
             userId:null, time:ts, raw:data};
});

if(!event) return null;

var colors = {UNLOCK:'green',ALARM:'red',ARMED:'yellow',DISARMED:'yellow',DOORBELL:'blue'};
var label  = event.method + (event.userName?' | '+event.userName:'') + ' @ ' + event.time;
node.status({fill:colors[event.type]||'grey', shape:'dot', text:label});
msg.payload = event;
return msg;

var C='YOUR_CLIENT_ID',S='YOUR_CLIENT_SECRET',D='YOUR_DEVICE_ID',B='https://openapi.tuyaeu.com';
var T=flow.get('TOKEN')||'';
if(!T){node.status({fill:'red',shape:'dot',text:'No token'});return null;}
var path = '/v1.1/devices/'+D+'/door-lock/offline-temp-password';
var now  = Math.floor(Date.now()/1000);

// Custom time from msg.payload or defaults to 1 hour
var effectiveTime = now;
var invalidTime   = now + 3600; // default 1 hour

if(msg.payload && typeof msg.payload === 'object'){
  // {hours: N} — valid for N hours from now
  if(msg.payload.hours){
    invalidTime = now + (parseInt(msg.payload.hours) * 3600);
  }
  // {from: 'YYYY-MM-DDTHH:MM', to: 'YYYY-MM-DDTHH:MM'}
  if(msg.payload.from){
    effectiveTime = Math.floor(new Date(msg.payload.from).getTime()/1000);
  }
  if(msg.payload.to){
    invalidTime = Math.floor(new Date(msg.payload.to).getTime()/1000);
  }
}

var body = JSON.stringify({type:'once', effective_time:effectiveTime, invalid_time:invalidTime});
var t    = String(Date.now());
var bh   = crypto.createHash('sha256').update(body).digest('hex');
var sts  = 'POST\n'+bh+'\n\n'+path;
var sig  = crypto.createHmac('sha256',S).update(C+T+t+sts).digest('hex').toUpperCase();
msg.method='POST'; msg.url=B+path; msg.payload=body;
msg.headers={'client_id':C,'access_token':T,'sign_method':'HMAC-SHA256','t':t,'nonce':'','sign':sig,'Content-Type':'application/json'};
var fromStr = new Date(effectiveTime*1000).toLocaleString('en-GB',{timeZone:'Asia/Riyadh'});
var toStr   = new Date(invalidTime*1000).toLocaleString('en-GB',{timeZone:'Asia/Riyadh'});
node.status({fill:'blue',shape:'ring',text:'Valid: '+fromStr+' → '+toStr});
return msg;

if(msg.payload&&msg.payload.success){
  var r   = msg.payload.result;
  var pwd = r.offline_temp_password;
  var frm = new Date(r.effective_time*1000).toLocaleString('en-GB',{timeZone:'Asia/Riyadh'});
  var exp = new Date(r.invalid_time*1000).toLocaleString('en-GB',{timeZone:'Asia/Riyadh'});
  flow.set('lastPwd', pwd);
  node.status({fill:'green',shape:'dot',text:'Code: '+pwd});
  msg.payload={
    success:  true,
    password: pwd,
    validFrom: frm,
    validUntil: exp,
    message: '🔑 Keypad Code: '+pwd+' | From: '+frm+' | Until: '+exp
  };
}else{
  node.status({fill:'red',shape:'dot',text:'Failed: '+JSON.stringify(msg.payload)});
}
return msg;

