};
var entries=logs.map(function(e){
  var t=new Date(e.update_time).toLocaleString('en-GB',{timeZone:'Asia/Riyadh'});
  // status is an OBJECT {code, value} — NOT an array
  var s      = e.status || {};
  var code   = s.code || '';
  var value  = s.value || '';
  var method = METHODS[code] || code || 'Unknown';
  var name   = e.nick_name || e.unlock_name || ('User #'+value);
  return {
    time:     t,
    method:   method,
    userName: name,
    userId:   value,
    raw:      e
  };
});
var last=entries[0];
node.status({fill:'blue',shape:'dot',
  text:last.time+' | '+last.method+' | '+last.userName});
msg.payload={total:msg.payload.result.total||entries.length,
  latest:last, all:entries};
