logs.forEach(function(e){
  var s    = e.status||{};
  var code = s.code||'unknown';
  var name = e.nick_name||e.unlock_name||('User #'+s.value);
  counts[code] = (counts[code]||0)+1;
  var t = new Date(e.update_time).toLocaleString('en-GB',{timeZone:'Asia/Riyadh'});
  if(!lastByUser[name]||e.update_time>lastByUser[name].ts){
    lastByUser[name]={ts:e.update_time,time:t,method:code};
  }
});

var METHODS={
  'unlock_fingerprint':'👆 Fingerprint',
  'unlock_password':   '🔢 Password',
  'unlock_temporary':  '🔑 Temp Code',
  'unlock_card':       '💳 Card',
  'unlock_app':        '📱 App',
  'unlock_face':       '😊 Face',
  'unlock_key':        '🗝 Key'
};

var summary=Object.keys(counts).map(function(k){
  return {method:METHODS[k]||k, count:counts[k]};
});

var userSummary=Object.keys(lastByUser).map(function(name){
  var u=lastByUser[name];
  return {user:name, lastSeen:u.time, method:METHODS[u.method]||u.method};
});

node.status({fill:'blue',shape:'dot',
  text:'7-day total: '+total+' unlocks'});
msg.payload={
  totalUnlocks: total,
  methodBreakdown: summary,
  userActivity: userSummary,
  note:'Real-time alarms shown in Lock Events debug node (local device)'
};
return msg;

