node.status({fill:'blue',shape:'ring',text:'Generating code for '+hours+'h...'});
return msg;

var r   = msg.payload && msg.payload.success ? msg.payload.result : null;
var pwd = r ? r.offline_temp_password : null;
var fromMs = r ? r.effective_time * 1000 : null;
var toMs   = r ? r.invalid_time   * 1000 : null;
var out = pwd
  ? {success:true, password:pwd, fromMs:fromMs, toMs:toMs}
