    <div class="lbl"><em>&#x23F1;</em> Select Duration</div>
    <div class="dur-grid">
      <button class="dur-btn active" onclick="pick(1,this)"><span class="num">1</span>hour</button>
      <button class="dur-btn" onclick="pick(2,this)"><span class="num">2</span>hours</button>
      <button class="dur-btn" onclick="pick(4,this)"><span class="num">4</span>hours</button>
      <button class="dur-btn" onclick="pick(8,this)"><span class="num">8</span>hours</button>
      <button class="dur-btn" onclick="pick(24,this)"><span class="num">1</span>day</button>
      <button class="dur-btn" onclick="pick(72,this)"><span class="num">3</span>days</button>
    </div>

    <div class="lbl" style="margin-bottom:10px;"><em>&#x2699;</em> Custom Hours</div>
    <div class="custom-row">
      <input class="custom-input" type="number" id="hrs" min="0.25" max="720"
             step="0.25" placeholder="e.g. 12" oninput="onCustom()"/>
      <span class="custom-unit">hours</span>
    </div>

    <div class="preview" id="preview">&#x23F0; Valid immediately &mdash; expires in <strong id="durLbl">1 hour</strong></div>

    <button class="gen-btn" id="genBtn" onclick="generate()">Generate Access Code</button>
    <div class="err" id="errBox"></div>
  </div>

  <div class="result" id="resultBox">
    <div class="rlbl">&#x2726; Access Code Ready</div>
    <div class="code" id="codeEl" onclick="copyCode()">&#x2014;</div>
    <div class="copy-tip">tap to copy</div>
    <div class="validity">
      <div class="vrow"><span class="vk">VALID FROM</span><span id="vFrom"></span></div>
      <div class="vrow"><span class="vk">VALID UNTIL</span><span id="vUntil"></span></div>
    </div>
  </div>
</div>

<script>
var sel = 1;

function pick(h, btn) {
  sel = h;
  document.querySelectorAll('.dur-btn').forEach(function(b){b.classList.remove('active');});
  btn.classList.add('active');
  document.getElementById('hrs').value = '';
  updatePreview();
}

function onCustom() {
  var v = parseFloat(document.getElementById('hrs').value);
  if(v > 0) {
    sel = v;
    document.querySelectorAll('.dur-btn').forEach(function(b){b.classList.remove('active');});
    updatePreview();
  }
}

function updatePreview() {
  var lbl = sel < 1  ? Math.round(sel*60)+' min'
          : sel === 1 ? '1 hour'
          : sel < 24  ? sel+' hours'
          : sel === 24 ? '1 day'
          : Math.round(sel/24)+' days';
  document.getElementById('durLbl').textContent = lbl;
}

function generate() {
  var btn = document.getElementById('genBtn');
  btn.textContent = 'Generating...'; btn.classList.add('loading');
  document.getElementById('errBox').classList.remove('show');
  document.getElementById('resultBox').classList.remove('show');

  fetch('/api/password', {
    method: 'POST',
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify({hours: sel})
  })
  .then(function(r){ return r.json(); })
  .then(function(d) {
    btn.textContent = 'Generate Access Code'; btn.classList.remove('loading');
    if(d.success) {
      document.getElementById('codeEl').textContent = d.password;
      var opts = {hour:'2-digit',minute:'2-digit',second:'2-digit',
                  day:'2-digit',month:'2-digit',year:'numeric'};
      document.getElementById('vFrom').textContent  =
        d.fromMs ? new Date(d.fromMs).toLocaleString(undefined,opts) : 'Now';
      document.getElementById('vUntil').textContent =
        d.toMs   ? new Date(d.toMs).toLocaleString(undefined,opts)   : '—';
      document.getElementById('resultBox').classList.add('show');
    } else {
      showErr(d.error || d.message || JSON.stringify(d));
    }
  })
  .catch(function(e){
    btn.textContent='Generate Access Code'; btn.classList.remove('loading');
    showErr('Network error: '+e.message);
  });
}

function copyCode(){
  var c = document.getElementById('codeEl').textContent;
  navigator.clipboard.writeText(c).then(function(){
    document.getElementById('codeEl').style.color='var(--green)';
    setTimeout(function(){document.getElementById('codeEl').style.color='';},1200);
  });
}

function showErr(m){
  var el=document.getElementById('errBox'); el.textContent='⚠ '+m; el.classList.add('show');
}

updatePreview();
</script>
</body>
</html>`;
msg.headers={'content-type':'text/html'};
msg.statusCode=200;
